const main = { preset: 'metal', color: params.color, metalness: 0.45, roughness: 0.42, flatShading: true };
const trim = { preset: 'metal', color: params.trimColor, metalness: 0.72, roughness: 0.28 };
const dark = { preset: 'metal', color: '#17191a', metalness: 0.65, roughness: 0.45 };
const steel = { preset: 'metal', color: '#70777a', metalness: 0.82, roughness: 0.3 };
const wood = { preset: 'wood', color: '#5a3924', roughness: 0.82 };
const glass = { preset: 'glass', color: '#9cc6cf', opacity: 0.72, roughness: 0.12 };
const lamp = { preset: 'emissive', color: '#ffe4a0', emissive: '#ffd36b', emissiveIntensity: 2.4 };
const railLen = 8.2;
const gauge = 1.28;
const wheelY = 0.61;
for (let i = 0; i < 11; i++) {
  const x = -railLen / 2 + i * railLen / 10;
  api.add(api.box(0.18, 0.12, 2.05).translate(x, 0.06, 0), wood);
}
for (let side = -1; side <= 1; side += 2) {
  api.add(api.box(railLen, 0.13, 0.09).translate(0, 0.19, side * gauge / 2), steel);
}
api.add(api.box(5.8, 0.24, 1.45).translate(-0.15, 0.72, 0), dark);
api.add(api.box(4.9, 0.12, 1.7).translate(-0.25, 0.92, 0), trim);
const boiler = api.cylinder(0.69, 0.69, 3.35, 20).rotate(0, 0, 90).translate(-0.35, 1.72, 0);
api.add(boiler, main);
api.add(api.cylinder(0.78, 0.78, 0.16, 20).rotate(0, 0, 90).translate(1.34, 1.72, 0), trim);
api.add(api.cylinder(0.73, 0.73, 0.17, 20).rotate(0, 0, 90).translate(-1.15, 1.72, 0), trim);
api.add(api.cylinder(0.73, 0.73, 0.17, 20).rotate(0, 0, 90).translate(0.42, 1.72, 0), trim);
api.add(api.cylinder(0.72, 0.72, 0.22, 20).rotate(0, 0, 90).translate(1.48, 1.72, 0), dark);
api.add(api.box(1.45, 1.75, 1.5).translate(-2.32, 1.74, 0), main);
api.add(api.box(1.58, 0.16, 1.68).translate(-2.32, 2.67, 0), trim);
api.add(api.box(1.35, 0.12, 1.54).translate(-2.32, 0.99, 0), dark);
for (let side = -1; side <= 1; side += 2) {
  api.add(api.box(0.64, 0.58, 0.035).translate(-2.34, 2.12, side * 0.756), glass);
  api.add(api.box(0.08, 0.66, 0.06).translate(-2.34, 2.12, side * 0.79), trim);
  api.add(api.box(0.72, 0.08, 0.06).translate(-2.34, 2.12, side * 0.79), trim);
}
api.add(api.box(0.68, 0.58, 0.04).translate(-1.58, 2.12, 0), glass);
api.add(api.box(0.08, 0.66, 1.56).translate(-1.62, 2.12, 0), trim);
const stackProfile = [[0,0],[0.28,0],[0.28,0.55],[0.43,0.82],[0.43,0.96],[0.23,1.02],[0,1.02]];
api.add(api.lathe(stackProfile, 16).translate(0.88, 2.31, 0), dark);
api.add(api.torus(0.42, 0.055).rotate(90,0,0).translate(0.88, 3.28, 0), trim);
const domeProfile = [[0,0],[0.31,0],[0.31,0.28],[0.25,0.43],[0.12,0.53],[0,0.55]];
api.add(api.lathe(domeProfile, 16).translate(-0.48, 2.34, 0), main);
api.add(api.torus(0.3, 0.045).rotate(90,0,0).translate(-0.48, 2.38, 0), trim);
api.add(api.cylinder(0.12, 0.18, 0.32, 12).translate(-1.04, 2.46, 0), trim);
api.add(api.sphere(0.16, 1).translate(-1.04, 2.67, 0), trim);
const wheelXs = [-1.35, -0.25, 0.85];
for (let s = -1; s <= 1; s += 2) {
  for (let i = 0; i < 3; i++) {
    const x = wheelXs[i];
    const z = s * 0.79;
    api.add(api.cylinder(0.54, 0.54, 0.14, 16).rotate(90,0,0).translate(x, wheelY, z), dark);
    api.add(api.torus(0.43, 0.075).translate(x, wheelY, z + s * 0.08), trim);
    api.add(api.cylinder(0.14, 0.14, 0.19, 12).rotate(90,0,0).translate(x, wheelY, z + s * 0.09), trim);
    for (let k = 0; k < 8; k++) {
      const a = k * Math.PI / 4;
      const sx = x + Math.cos(a) * 0.23;
      const sy = wheelY + Math.sin(a) * 0.23;
      api.add(api.box(0.38, 0.055, 0.045).rotate(0,0,k * 45).translate(sx, sy, z + s * 0.16), trim);
    }
  }
  api.add(api.box(2.55, 0.1, 0.09).rotate(0,0,3).translate(-0.25, 0.62, s * 0.98), trim);
  api.add(api.box(1.45, 0.075, 0.075).rotate(0,0,-16).translate(0.25, 0.86, s * 0.99), steel);
}
for (let s = -1; s <= 1; s += 2) {
  api.add(api.cylinder(0.3,0.3,0.13,14).rotate(90,0,0).translate(-2.65,0.52,s*0.72), dark);
  api.add(api.cylinder(0.18,0.18,0.16,12).rotate(90,0,0).translate(-2.65,0.52,s*0.82), trim);
}
api.add(api.box(0.9, 0.52, 1.25).translate(1.78, 1.08, 0), main);
api.add(api.cylinder(0.13,0.13,0.18,12).rotate(90,0,0).translate(2.26,1.74,0), trim);
api.add(api.sphere(0.19,1).scale(1,1,0.55).translate(2.31,1.91,0), lamp);
api.add(api.box(0.12,0.72,1.72).rotate(0,0,-31).translate(2.71,0.62,0), dark);
for (let s = -1; s <= 1; s += 2) {
  for (let i = 0; i < 5; i++) {
    const z = s * (0.16 + i * 0.17);
    api.add(api.box(1.28,0.065,0.055).rotate(0,0,-13).translate(2.68,0.47,z), steel);
  }
  api.add(api.box(0.09,0.6,0.09).rotate(0,0,-31).translate(2.74,0.62,s*0.82), trim);
}
api.add(api.box(0.13,0.13,1.82).translate(3.18,0.32,0), trim);
api.add(api.box(0.16,0.16,1.48).translate(-3.04,0.76,0), dark);
api.add(api.cylinder(0.08,0.08,0.72,10).rotate(0,0,90).translate(1.95,1.03,0.66), trim);
api.add(api.cylinder(0.08,0.08,0.72,10).rotate(0,0,90).translate(1.95,1.03,-0.66), trim);
api.collider({ kind: 'box', halfExtents: [2.9,0.7,0.72], offset: [-0.15,1.18,0] });
api.collider({ kind: 'box', halfExtents: [0.74,0.88,0.76], offset: [-2.32,1.78,0] });
api.collider({ kind: 'cylinder', radius: 0.7, halfHeight: 1.68, offset: [-0.35,1.72,0], rotation: [0,0,90] });
api.collider({ kind: 'box', halfExtents: [4.1,0.13,1.03], offset: [0,0.13,0] });
return api.build();
